<?php
require_once __DIR__.'/../config/app.php';
require_role('member');
$pageTitle='Fitness goals'; $userId=(int)current_user()['id']; $message=''; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $action=$_POST['action']??'';
 if($action==='create'){
  $title=trim($_POST['title']??'');$type=$_POST['goal_type']??'custom';$target=(float)($_POST['target_value']??0);$unit=trim($_POST['unit']??'');$date=$_POST['target_date']??'';
  if($title===''||strlen($title)>150||!in_array($type,['weight','workouts','attendance','minutes','custom'],true)||$target<=0||$target>100000||strlen($unit)>30||($date!==''&&$date<date('Y-m-d'))) $error='Enter a title, a positive target and a valid target date.';
  else {$q=$pdo->prepare("INSERT INTO fitness_goals(member_id,title,goal_type,target_value,unit,target_date) VALUES(?,?,?,?,?,?)");$q->execute([$userId,$title,$type,$target,$unit,$date?:null]);$message='Your new goal has been created.';}
 } elseif($action==='update'){
  $id=(int)($_POST['goal_id']??0);$current=(float)($_POST['current_value']??0);
  if($id<1||$current<0||$current>100000)$error='Enter a valid progress value.';
  else {$q=$pdo->prepare("UPDATE fitness_goals SET current_value=?,status=IF(? >= target_value,'completed','active') WHERE id=? AND member_id=?");$q->execute([$current,$current,$id,$userId]);$message='Goal progress updated.';}
 }
}
$q=$pdo->prepare("SELECT * FROM fitness_goals WHERE member_id=? ORDER BY FIELD(status,'active','paused','completed'),target_date IS NULL,target_date ASC,created_at DESC");$q->execute([$userId]);$goals=$q->fetchAll();
$goalVisuals=[
 'weight'=>['label'=>'Body transformation','image'=>'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=900&q=85','hint'=>'Work toward your chosen weight and body-composition milestone.'],
 'workouts'=>['label'=>'Stronger & more muscular','image'=>'https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?auto=format&fit=crop&w=900&q=85','hint'=>'Build strength through consistent, progressive training.'],
 'attendance'=>['label'=>'Consistent gym routine','image'=>'https://images.unsplash.com/photo-1534258936925-c58bed479fcb?auto=format&fit=crop&w=900&q=85','hint'=>'Make showing up and building a routine your destination.'],
 'minutes'=>['label'=>'Endurance & stamina','image'=>'https://images.unsplash.com/photo-1538805060514-97d9cc17730c?auto=format&fit=crop&w=900&q=85','hint'=>'Build your training capacity and cardiovascular fitness.'],
 'custom'=>['label'=>'Your personal fitness vision','image'=>'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?auto=format&fit=crop&w=900&q=85','hint'=>'Choose a meaningful target and make it your own.']
];
include __DIR__.'/../includes/header.php'; ?>
<div class="dashboard-layout"><?php include __DIR__.'/../includes/sidebar.php'; ?><main class="dashboard-main member-dashboard"><div class="dash-top"><div><span class="eyebrow">PERSONAL TARGETS</span><h1>Fitness goals</h1><p class="dash-subtitle">Set a target, update your progress and keep your next milestone in sight.</p></div><span class="user-pill"><?= e(current_user()['name']) ?></span></div>
<?php if($message): ?><p class="form-success"><?= e($message) ?></p><?php endif; ?><?php if($error): ?><p class="form-error"><?= e($error) ?></p><?php endif; ?>
<section class="goal-vision-section"><div class="goal-vision-copy"><span class="eyebrow">VISUALISE YOUR NEXT LEVEL</span><h2>Your goal. Your destination.</h2><p>Choose the outcome you want to work toward. The image stays with the matching goal category on your goal board.</p></div><div class="goal-vision-grid">
<?php foreach($goalVisuals as $key=>$visual): ?><button type="button" class="goal-vision-card" data-goal-choice="<?= e($key) ?>"><img src="<?= e($visual['image']) ?>" alt="<?= e($visual['label']) ?>" loading="lazy"><span><?= e($visual['label']) ?></span><small><?= e($visual['hint']) ?></small></button><?php endforeach; ?>
</div></section>
<section class="member-card activity-form-card"><div class="card-heading"><div><span class="eyebrow">SET YOUR NEXT MILESTONE</span><h2>Create a goal</h2></div><span class="form-symbol">◎</span></div><form method="post" class="activity-form"><?= csrf_field() ?><input type="hidden" name="action" value="create"><label>Goal title<input name="title" maxlength="150" placeholder="e.g. Build a consistent training routine" required></label><label>Goal category<select id="goal-type-select" name="goal_type"><option value="custom">Personal goal</option><option value="weight">Weight</option><option value="workouts">Workouts</option><option value="attendance">Gym visits</option><option value="minutes">Training minutes</option></select></label><div class="goal-selected-visual" id="goal-selected-visual"><img src="<?= e($goalVisuals['custom']['image']) ?>" alt="Your selected fitness destination"><div><strong><?= e($goalVisuals['custom']['label']) ?></strong><span><?= e($goalVisuals['custom']['hint']) ?></span></div></div><label>Target value<input type="number" name="target_value" min="0.1" step="0.1" placeholder="12" required></label><label>Unit<input name="unit" maxlength="30" placeholder="sessions, kg, visits..."></label><label>Target date<input type="date" name="target_date" min="<?= date('Y-m-d') ?>"></label><div class="wide-field"><button class="btn btn-dark">Create goal →</button></div></form></section>
<section class="member-card"><div class="card-heading"><div><span class="eyebrow">YOUR COMMITMENTS</span><h2>Goal board</h2></div><span class="notification-count"><?= count($goals) ?> total</span></div><?php if($goals): ?><div class="goal-board"><?php foreach($goals as $g): $pct=$g['target_value']>0?min(100,max(0,((float)$g['current_value']/(float)$g['target_value'])*100)):0; ?><article class="goal-card"><img class="goal-card-image" src="<?= e($goalVisuals[$g['goal_type']]['image']??$goalVisuals['custom']['image']) ?>" alt="Fitness goal inspiration" loading="lazy"><div class="goal-card-content"><div class="goal-card-top"><div><strong><?= e($g['title']) ?></strong><span><?= e(ucfirst($g['goal_type'])) ?><?= $g['target_date']?' · Due '.e(date('d M Y',strtotime($g['target_date']))):'' ?></span></div><span class="status-chip <?= e($g['status']) ?>"><?= e(ucfirst($g['status'])) ?></span></div><div class="goal-numbers"><strong><?= e(rtrim(rtrim(number_format((float)$g['current_value'],1),'0'),'.')) ?></strong><span>of</span><strong><?= e(rtrim(rtrim(number_format((float)$g['target_value'],1),'0'),'.')) ?> <?= e($g['unit']) ?></strong><b><?= round($pct) ?>%</b></div><div class="progress-track"><span style="width:<?= $pct ?>%"></span></div><?php if($g['status']!=='completed'): ?><form method="post" class="goal-update-form"><?= csrf_field() ?><input type="hidden" name="action" value="update"><input type="hidden" name="goal_id" value="<?= (int)$g['id'] ?>"><label>Update progress<input type="number" name="current_value" min="0" max="100000" step="0.1" value="<?= e($g['current_value']) ?>" required></label><button class="btn btn-outline-purple btn-small">Save progress</button></form><?php endif; ?></div></article><?php endforeach; ?></div><?php else: ?><p class="empty-note">You haven't created a goal yet. Start with a small, measurable milestone.</p><?php endif; ?></section>
</main></div><script>
(()=>{const data=<?= json_encode($goalVisuals,JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;const select=document.getElementById('goal-type-select');const preview=document.getElementById('goal-selected-visual');function show(key){const item=data[key]||data.custom;if(preview){preview.querySelector('img').src=item.image;preview.querySelector('img').alt=item.label;preview.querySelector('strong').textContent=item.label;preview.querySelector('span').textContent=item.hint;}document.querySelectorAll('[data-goal-choice]').forEach(el=>el.classList.toggle('selected',el.dataset.goalChoice===key));}if(select){select.addEventListener('change',()=>show(select.value));show(select.value);}document.querySelectorAll('[data-goal-choice]').forEach(el=>el.addEventListener('click',()=>{if(select){select.value=el.dataset.goalChoice;show(select.value);select.scrollIntoView({behavior:'smooth',block:'center'});}}));})();
</script><script src="<?= BASE_URL ?>/assets/js/main.js"></script></body></html>
